 void runEventRelease(){kstation::NativeMidiEvents t;kstation::NativeVoiceAddress addr;unsigned steps=0;while(uint32_t(a->getPC())!=0x35fc||t.active()||!steps){check(++steps<100,"event release hang");if(t.step(*b)){a->step();equal();++phases;continue;}auto child=t.external();check(child==kstation::NativeMidiEvents::External::VoiceAddress,"event release external");while(!addr.complete()){check(addr.step(*b),"event voice address");a->step();equal();++phases;}++children;}}
