 void owner(uint8_t flags,uint8_t newPolicy,uint8_t oldPolicy,uint16_t phase,bool held){prep(0x3446,flags);wide(0xbfaa,0x200100);byte(0x200180,0);byte(0x200181,0);byte(0xd02c,0);byte(0xd0ee,0);byte(0x200156,64);byte(0x200157,3);byte(0x200158,newPolicy);byte(0xcd26,oldPolicy);byte(0xcc02,0);word(0xc492,0);word(0xc494,200);byte(0xbb17,0);byte(0xcd3d,1);word(0xcd3e,0);word(0xcd34,phase);byte(0xcd3c,60);byte(0xd022,1);word(0xd038,0);for(unsigned i=0;i<16;++i)byte(0xcbee +i,0);if(held)byte(0xcbee,1);wide(0xfffe50,0x12345678);wide(0xcd28,0x12345677);wide(0xcd2c,0);wide(0xcd30,0x81234567);kstation::NativeArp t;using X=kstation::NativeArp::External;unsigned steps=0;while(uint32_t(a->getPC())!=0x7000||t.active()){check(++steps<500,"arp owner hang");auto at=uint32_t(a->getPC());if(t.step(*b)){a->step();equal();++phases;continue;}equal();auto child=t.external();check(child!=X::None,"arp owner unexplained reject");uint32_t expected=child==X::ReleaseVoices?0x7644:child==X::Step?0x35fe:child==X::SendOutput?0x255a:child==X::Release?0x759a:child==X::RandomIndex?0x3660:child==X::OtherMode?0x368a:child==X::Tick?0x9aa:child==X::Schedule?0x354e:child==X::StartVoice?0x33f4:0x37ce;check(at==expected,"arp owner external target");if(child==X::Release)runEventRelease();else if(child==X::StartVoice)runEventTrigger();else if(child==X::Tick)runTick();else{auto u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}++children;}++graphs;}
